const ui=(name,cls='')=>`<svg class="ui-icon ${cls}" aria-hidden="true" viewBox="0 0 24 24"><use href="vendor/icons.svg#${name}"></use></svg>`;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed={courses:[{id:'stats',name:'Xác suất & thống kê',icon:'◒',color:'sage',goal:'Hiểu xác suất để phân tích dữ liệu',progress:38,lesson:'Biến cố & xác suất',time:'20:00',date:'2026-11-12',duration:30,notes:'Độc lập khác với xung khắc. Cần tự tìm thêm ví dụ.',messages:[],sources:['s1','s2','s3','s4','s5'],plan:false,quiz:false},{id:'english',name:'Tiếng Anh giao tiếp',icon:'Aa',color:'clay',goal:'Tự tin giao tiếp trong công việc',progress:24,lesson:'Nói về một ngày làm việc',time:'20:00',date:'2026-11-13',duration:25,notes:'',messages:[],sources:['e1','e2','e3'],plan:false,quiz:false},{id:'python',name:'Lập trình Python',icon:'⌘',color:'blue',goal:'Tự viết công cụ xử lý dữ liệu',progress:12,lesson:'Vòng lặp & danh sách',time:'09:00',date:'2026-11-14',duration:40,notes:'',messages:[],sources:['p1','p2','p3','s5'],plan:false,quiz:false}],files:[['s1','Giáo trình Xác suất thống kê','Giáo trình nền tảng','PDF',248,'Sách chính'],['s2','Introduction to Probability','Sách tham khảo','PDF',536,'Đào sâu'],['s3','Bài giảng — Xác suất có điều kiện','Slide trên lớp','PDF',42,'Bài giảng'],['s4','Bài tập xác suất theo chủ đề','Ngân hàng bài tập','PDF',96,'Luyện tập'],['s5','Ghi chú — Tư duy với dữ liệu','Ghi chú cá nhân · dùng cho 2 môn','MD',8,'Bổ trợ'],['e1','English for Everyday Conversations','Giáo trình giao tiếp','PDF',180,'Sách chính'],['e2','Workplace English — Lesson Notes','Bài giảng công việc','PDF',64,'Bài giảng'],['e3','My vocabulary notebook','Từ vựng cá nhân','MD',12,'Ôn tập'],['p1','Python Crash Course','Giáo trình lập trình','PDF',544,'Sách chính'],['p2','Automate the Boring Stuff','Thực hành dự án','PDF',592,'Thực hành'],['p3','Bài tập Python cơ bản','Ngân hàng bài tập','PDF',48,'Luyện tập']].map(([id,name,author,kind,pages,role])=>({id,name,author,kind,pages,role,sample:true})),tele:[]};
let state;try{state=JSON.parse(localStorage.getItem('nhiphoc-v2'))}catch{}if(!state?.courses?.length)state=structuredClone(seed);
let page='home',courseId='stats',tab='overview',libraryFilter='all',search='',sourceFocus=null,studyMode='chat';
function save(){try{localStorage.setItem('nhiphoc-v2',JSON.stringify(state))}catch{toast('Chưa lưu được vào trình duyệt. Bạn vẫn có thể thử giao diện.')}}
const course=()=>state.courses.find(c=>c.id===courseId)||state.courses[0],filesFor=c=>c.sources.map(id=>state.files.find(f=>f.id===id)).filter(Boolean),pill=t=>`<span class="label">${esc(t)}</span>`,icon=c=>`<span class="subject-icon ${c.color}">${ui(c.id==='stats'?'school':c.id==='english'?'language':c.id==='python'?'code':'book')}</span>`;
const intro=(e,t,d,a='')=>`<section class="intro"><div><div class="eyebrow">${e}</div><h1>${t}</h1><p class="muted">${d}</p></div>${a}</section>`;
const dateName=d=>d==='2026-11-12'?'Hôm nay':d==='2026-11-13'?'Ngày mai':new Date(d+'T12:00:00').toLocaleDateString('vi-VN',{day:'numeric',month:'numeric'}),sorted=()=>[...state.courses].sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3500)}
function go(p,cid,t){page=p;if(cid)courseId=cid;if(t)tab=t;else if(p==='course')tab='overview';history.replaceState(null,'','#'+(p==='course'?`course/${courseId}/${tab}`:p));render();window.scrollTo(0,0)}
function render(){$('#fileCount').textContent=state.files.length;$('#courseNav').innerHTML=state.courses.map(c=>`<button class="course-link ${page==='course'&&courseId===c.id?'selected':''}" data-course="${c.id}">${icon(c)}<span>${esc(c.name)}</span><i></i></button>`).join('');$$('#globalnav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#crumb').innerHTML=`Không gian học tập <b>/</b> ${page==='home'?'Tổng quan':page==='library'?'Thư viện chung':page==='schedule'?'Lịch & Telegram':esc(course().name)}`;$('#content').innerHTML=page==='home'?homeView():page==='library'?libraryView():page==='schedule'?scheduleView():courseView();bind()}
function homeView(){const next=sorted()[0];return intro('KHÔNG GIAN HỌC TẬP','Học theo cách của bạn.','Một chút tập trung hôm nay. Một bước tiến cho ngày mai.','<button class="primary" data-action="newCourse">'+ui('plus')+' Tạo môn học</button>')+`<div class="overview-layout"><section><div class="nextsession"><div class="hero-copy"><span class="hero-kicker"><i></i> TIẾP TỤC CHẶNG ĐƯỜNG</span><div class="nextsubject">${esc(next.name)} <span>·</span> ${dateName(next.date)}, ${next.time}</div><h2>${esc(next.lesson)}</h2><p>Hiểu qua ví dụ. Hỏi đến tận cùng.<br>Gia sư đã sẵn sàng cùng bạn.</p><button class="primary" data-course="${next.id}" data-tab="study">${ui('player-play')} Vào bàn học ${ui('arrow-right')}</button><div class="hero-foot">${ui('clock')} ${next.duration} phút <span>·</span> ${filesFor(next).length} nguồn tài liệu</div></div><div class="hero-visual" aria-hidden="true"><div class="orbital"><div class="orbital-inner"></div><span class="planet one"></span><span class="planet two"></span><span class="planet three"></span><div class="orbit-core">${ui('brain')}</div></div><div class="floating-tag">${ui('sparkles')} Gia sư của riêng bạn</div></div></div><div class="rowtitle"><div><h3>Môn học của bạn <span class="count">${state.courses.length}</span></h3><p>Mỗi môn một hành trình. Cùng tiến lên từng chút.</p></div><button class="textbutton" data-action="newCourse">${ui('plus')} Thêm môn</button></div><div class="course-grid">${state.courses.map((c,i)=>`<button class="course-card card" data-course="${c.id}"><div class="course-cover ${c.color}"><div class="cover-grid"></div><span class="cover-index">${String(i+1).padStart(2,'0')} / NHỊP HỌC</span><span class="cover-subject">${ui(c.id==='stats'?'school':c.id==='english'?'language':c.id==='python'?'code':'book')}</span><span class="cover-decoration">${c.id==='stats'?'P(A)':c.id==='english'?'Hello.':c.id==='python'?'&lt;/&gt;':'Learn.'}</span><span class="cover-arrow">${ui('arrow-up-right')}</span></div><div class="course-body"><h3>${esc(c.name)}</h3><p>${esc(c.goal)}</p><div class="course-meta"><span>${ui('books')} ${c.sources.length} tài liệu</span><span>${c.progress}%</span></div><div class="bar"><i style="width:${c.progress}%"></i></div><div class="course-bottom"><span>${ui('clock')} ${dateName(c.date)} · ${c.time}</span>${ui('arrow-right')}</div></div></button>`).join('')}</div><div class="library-strip"><span class="strip-icon">${ui('layers-linked')}</span><div><h3>Nhiều cuốn sách. Một hướng đi.</h3><p>Kết nối ${state.files.length} nguồn tài liệu để tạo lộ trình của riêng bạn.</p></div><button class="textbutton" data-page="library">Mở thư viện ${ui('arrow-up-right')}</button></div></section><aside><div class="panel today-panel"><div class="panelhead"><h3>Nhịp học tuần này</h3><button class="icon-button" data-page="schedule" aria-label="Mở lịch học">${ui('arrow-up-right')}</button></div><div class="mini-month"><span>Tháng 11, 2026</span>${ui('calendar')}</div><div class="mini-week">${['T2|9','T3|10','T4|11','T5|12','T6|13','T7|14','CN|15'].map((d,i)=>`<div class="${i===3?'selected':''}"><span>${d.split('|')[0]}</span><b>${d.split('|')[1]}</b><i class="${i>2&&i<6?'has-session':''}"></i></div>`).join('')}</div><div class="agenda-title">SẮP TỚI <span>${state.courses.length} buổi học</span></div>${sorted().slice(0,3).map(c=>`<button class="upcoming" data-course="${c.id}" data-tab="study"><span class="session-dot ${c.color}"></span><div><div class="subject-small ${c.color}">${esc(c.name)}</div><h4>${esc(c.lesson)}</h4><small>${dateName(c.date)} · ${c.time} <span>· ${c.duration} phút</span></small></div>${ui('chevron-right')}</button>`).join('')}<button class="secondary full" data-page="schedule">Xem lịch học ${ui('arrow-right')}</button></div><div class="telegram">${telehead()}<p>Lịch thay đổi? Cứ nhắn.<br>Mình tìm một nhịp phù hợp hơn.</p><div class="preview-tele-bubble">Nay bận rồi, mai học nhé?<span>18:42 ${ui('circle-check')}</span></div><button data-page="schedule">Thử sắp xếp lại ${ui('arrow-right')}</button></div><div class="memory-note"><span>${ui('sparkles')}</span><div><h3>Học tiếp, không kể lại.</h3><p>Lộ trình, ghi chú và cuộc trò chuyện được lưu riêng cho từng môn.</p></div></div></aside></div>`}
function sourceItem(f,open=false){return `<div class="source-item"><span class="book-icon ${f.kind==='MD'?'blue':'sage'}">${esc(f.kind)}</span><div class="source-info"><h3>${esc(f.name)}</h3><p>${esc(f.author)} · ${f.sample?'Nguồn mẫu':'Chưa phân tích nội dung'}</p><div class="source-tags">${pill(f.role)}<span>${f.sample?f.pages+' trang minh họa':'Chỉ lưu tên tệp'}</span></div></div>${open?`<button class="secondary" data-open-source="${f.id}">Xem ↗</button>`:`<span class="source-check">${ui('circle-check')}</span>`}</div>`}
function libraryView(){const list=state.files.filter(f=>(libraryFilter==='all'||state.courses.find(c=>c.id===libraryFilter)?.sources.includes(f.id))&&f.name.toLowerCase().includes(search.toLowerCase()));return intro('THƯ VIỆN CHUNG','Mọi nguồn học, ở cùng một chỗ.','Sách, slide, bài tập và ghi chú. Dùng lại cho nhiều môn, ghép thành một lộ trình.','<button class="primary" data-action="upload">↥ Thêm tài liệu</button>')+`<div class="library-toolbar"><div class="filter-tabs"><button data-filter="all" class="${libraryFilter==='all'?'active':''}">Tất cả <span>${state.files.length}</span></button>${state.courses.map(c=>`<button data-filter="${c.id}" class="${libraryFilter===c.id?'active':''}">${esc(c.name)}</button>`).join('')}</div><input id="search" aria-label="Tìm tài liệu" placeholder="⌕ Tìm tài liệu…" value="${esc(search)}"></div><div class="library-layout"><div class="panel">${list.length?list.map(f=>{const related=state.courses.filter(c=>c.sources.includes(f.id));return `<div class="library-file">${sourceItem(f,true)}<div class="usedby"><span>Dùng trong</span>${related.length?related.map(c=>`<button class="subject-small ${c.color}" data-course="${c.id}" data-tab="sources">${esc(c.name)}</button>`).join(''):'<span>Chưa gắn môn học</span>'}<button class="textbutton" data-assign="${f.id}">+ Gắn vào môn</button></div></div>`}).join(''):'<div class="empty">Chưa có tài liệu phù hợp.</div>'}</div><aside><div class="panel library-guide"><div class="eyebrow">KHÔNG CHỈ MỘT CUỐN SÁCH</div><h2>Nhiều nguồn.<br>Một hướng đi.</h2><div class="bookstack" aria-hidden="true"><i>01</i><i>02</i><i>03</i></div><p class="muted">Chọn 4–5 sách cho một môn. Đặt một cuốn làm nền tảng, những cuốn còn lại để bổ sung, đối chiếu hoặc luyện tập.</p><button class="secondary full" data-course="stats" data-tab="sources">Thử với môn Xác suất →</button></div><div class="memory-note"><span>↗</span><h3>Ghi chú cũng là một nguồn.</h3><p>Điều bạn tự đúc kết có thể ở cạnh sách và bài giảng, trong cùng không gian môn học.</p></div></aside></div>`}
function courseView(){const c=course();return `<div class="course-heading"><div class="course-identity">${icon(c)}<div><div class="eyebrow">KHÔNG GIAN MÔN HỌC</div><h1>${esc(c.name)}</h1><p class="muted">${esc(c.goal)}</p></div></div><button class="secondary" data-action="switchCourse">Đổi môn ⌄</button></div><div class="course-tabs">${[['overview',ui('layout-dashboard')+' Tổng quan'],['sources',ui('books')+' Tài liệu'],['path',ui('route')+' Lộ trình'],['study',ui('sparkles')+' Bàn học'],['practice',ui('pencil')+' Luyện tập']].map(([id,n])=>`<button data-tab="${id}" class="${tab===id?'active':''}">${n}${id==='sources'?` <small>${c.sources.length}</small>`:''}</button>`).join('')}</div>${tab==='overview'?courseOverview(c):tab==='sources'?courseSources(c):tab==='path'?pathView(c):tab==='study'?studyView(c):practiceView(c)}`}
function courseOverview(c){return `<div class="overview-layout"><section><div class="hero coursehero"><div class="tag">ĐANG HỌC · ${c.progress}% CHẶNG ĐƯỜNG</div><h2>${esc(c.lesson)}</h2><p>Dành ${c.duration} phút để hiểu một điều mới. Gia sư sẽ tiếp tục từ chỗ bạn đang học dở.</p><button class="primary" data-tab="study">Mở bàn học ↗</button><div class="hero-art" aria-hidden="true"><span>${ui(c.id==='stats'?'school':c.id==='english'?'language':c.id==='python'?'code':'book')}</span></div></div><div class="rowtitle"><h3>Tài liệu cùng tạo nên lộ trình</h3><button class="textbutton" data-tab="sources">Quản lý nguồn →</button></div><div class="panel compact-sources">${filesFor(c).slice(0,3).map(f=>sourceItem(f)).join('')}${c.sources.length>3?`<button class="textbutton more-sources" data-tab="sources">+ ${c.sources.length-3} nguồn bổ sung</button>`:''}${!c.sources.length?'<p class="muted">Thêm nguồn để cùng gia sư xây lộ trình.</p>':''}</div><div class="cards" style="margin-top:18px"><div class="card"><div class="icon">${ui('route')}</div><h3>Lộ trình từ nhiều nguồn</h3><p>Ghép các chương liên quan, chọn sách chính và tránh học trùng lặp.</p><button data-tab="path">Xem lộ trình →</button></div><div class="card"><div class="icon">${ui('pencil')}</div><h3>Hiểu rồi, thử một chút</h3><p>Quiz của bài đang học, có giải thích và gợi ý ôn lại.</p><button data-tab="practice">Luyện tập →</button></div></div></section><aside><div class="panel"><div class="eyebrow">MỤC TIÊU & NHỊP HỌC</div><h2>${esc(c.goal)}</h2><p class="muted">Buổi tiếp theo</p><h3>${dateName(c.date)}, ${c.time} · ${c.duration} phút</h3><div class="bar" style="margin:25px 0 10px"><i style="width:${c.progress}%"></i></div><p class="muted">Tiến độ mẫu: ${c.progress}%</p><button class="secondary full" data-page="schedule">Điều chỉnh lịch học</button></div><div class="memory-note"><span>✧</span><h3>Gia sư ghi nhớ riêng môn này</h3><p>${c.id==='stats'?'Bạn thích ví dụ trực quan. Cần phân biệt rõ biến cố độc lập và xung khắc.':c.id==='english'?'Bạn muốn luyện hội thoại công việc. Ưu tiên ví dụ ngắn, dùng được ngay.':c.id==='python'?'Bạn thích học bằng dự án nhỏ. Nên tự viết thử trước khi xem lời giải.':'Chưa có lịch sử. Bắt đầu từ mục tiêu và kiến thức nền của bạn.'}</p></div></aside></div>`}
function courseSources(c){return `<div class="section-intro"><div><h2>Nhiều cuốn sách, một môn học.</h2><p class="muted">Chọn sách chính và các nguồn bổ sung. Bạn quyết định khi nào cập nhật lộ trình.</p></div><button class="primary" data-action="pickSources">+ Chọn từ thư viện</button></div><div class="sources-layout"><div class="panel">${filesFor(c).map(f=>`<div class="source-row">${sourceItem(f,true)}<button class="remove-source" data-remove-source="${f.id}" aria-label="Bỏ nguồn khỏi môn">×</button></div>`).join('')||'<div class="empty">Chưa có nguồn. Chọn từ thư viện hoặc thêm tệp mới.</div>'}<button class="upload-inline" data-action="upload">${ui('upload')} Thêm sách, slide hoặc ghi chú mới</button></div><aside class="panel source-strategy"><div class="eyebrow">CÁCH DÙNG CÁC NGUỒN</div><h2>Không cần đọc tất cả<br>từ đầu đến cuối.</h2>${[['Một nguồn làm trục chính','Giữ mạch kiến thức xuyên suốt.'],['Các nguồn để bổ sung','Ví dụ khác, góc nhìn khác, bài tập thêm.'],['Một lộ trình để theo','Mỗi bài ghi rõ học ở nguồn nào.']].map(([t,p],i)=>`<div class="strategy-step"><b>0${i+1}</b><p><strong>${t}</strong><br>${p}</p></div>`).join('')}<button class="primary full" data-action="buildPlan">✧ Ghép thành lộ trình mẫu</button><p class="muted" style="font-size:10px">Đề xuất minh họa từ tên nguồn đã chọn. Chưa đọc hay so sánh nội dung sách.</p></aside></div>`}
function planTitles(c){return c.id==='stats'?['Nền tảng & quy tắc đếm','Biến cố & xác suất','Xác suất có điều kiện & Bayes','Biến ngẫu nhiên & phân phối','Thống kê mô tả & ước lượng','Dự án nhỏ: đọc một bộ dữ liệu']:c.id==='english'?['Làm quen & giới thiệu bản thân','Nói về một ngày làm việc','Đặt câu hỏi & làm rõ ý','Họp và trao đổi công việc','Bày tỏ quan điểm & phản biện','Thực hành một buổi phỏng vấn']:c.id==='python'?['Làm quen Python & biến','Vòng lặp & danh sách','Hàm & tổ chức mã','Đọc ghi tệp & xử lý lỗi','Làm việc với dữ liệu','Dự án: tự động hóa báo cáo']:['Kiến thức nền & kiểm tra đầu vào','Làm quen các khái niệm chính','Luyện tập có hướng dẫn','Kết nối các ý tưởng','Ứng dụng thực tế','Tổng kết & tự kiểm tra']}
function pathView(c){const fs=filesFor(c);return `<div class="section-intro"><div><h2>Một lộ trình, kết nối ${fs.length} nguồn.</h2><p class="muted">${c.plan?'Đề xuất mẫu đã được bạn áp dụng.':'Lộ trình minh họa · Xem đề xuất trước khi áp dụng.'}</p></div><button class="secondary" data-action="buildPlan">✧ ${c.plan?'Điều chỉnh lộ trình':'Tạo từ tài liệu đã chọn'}</button></div><div class="plan-summary"><span>◎ ${esc(c.goal)}</span><span>6 chặng học</span><span>◷ ${esc(c.pace||'Nhịp độ linh hoạt')}</span></div><div class="panel roadmap">${planTitles(c).map((t,i)=>{const f=fs[i%Math.max(fs.length,1)],extra=fs.length>1?fs[(i+1)%fs.length]:null;return `<div class="roadmap-row"><div class="roadmap-marker ${i===0?'done':i===1?'current':''}">${i===0?'✓':String(i+1).padStart(2,'0')}</div><div class="roadmap-main"><div class="panelhead"><h3>${esc(t)}</h3>${pill(i===0?'Đã học':i===1?'Đang học':'Sắp tới')}</div><p class="muted">${i===0?'Xây nền tảng và ôn lại những ý quan trọng.':i===1?'Học qua ví dụ, trao đổi cách hiểu và kiểm tra nhanh.':'Đọc có chọn lọc, đối chiếu cách giải thích và thực hành.'}</p><div class="roadmap-sources">${f?`<button data-open-source="${f.id}">▤ ${esc(f.name)} <small>· Chương ${i+1} (mẫu)</small></button>`:'<span class="muted">Chưa chọn tài liệu</span>'}${extra?`<button data-open-source="${extra.id}">↗ ${esc(extra.name)} <small>· Bổ sung</small></button>`:''}</div></div><button class="textbutton" data-tab="study">${i===0?'Ôn lại':'Vào học'} ↗</button></div>`}).join('')}</div><div class="notice">${ui('sparkles')} Chương và quan hệ giữa các nguồn là dữ liệu mẫu. Bản thật cần AI đọc nội dung và bạn duyệt đề xuất.</div>`}
function readerContent(c,f){if(!f)return '<div class="empty">Chọn hoặc thêm một tài liệu để bắt đầu.</div>';if(!f.sample)return `<div class="reading-page"><div class="eyebrow">TỆP ĐÃ CHỌN · CHƯA PHÂN TÍCH</div><h2>${esc(f.name)}</h2><p>Bản thử chỉ giữ tên tài liệu. Nội dung tệp chưa được tải lên máy chủ hoặc đọc bởi AI.</p><button class="secondary" data-action="pickSources">Chọn thêm nguồn mẫu</button></div>`;return `<div class="reading-page"><div class="eyebrow">NỘI DUNG BIÊN SOẠN MINH HỌA · KHÔNG PHẢI TRÍCH SÁCH</div><h2>${esc(c.lesson)}</h2><p>${c.id==='stats'?'Xác suất giúp ta mô tả mức độ có thể xảy ra của một biến cố. Trước hết, cần xác định rõ không gian mẫu và điều kiện của phép thử.':c.id==='english'?'Một đoạn hội thoại hiệu quả bắt đầu từ những câu đơn giản, rõ ý. Hãy thử kể về một ngày làm việc của bạn bằng ba câu ngắn.':c.id==='python'?'Vòng lặp giúp bạn thực hiện một thao tác trên nhiều phần tử. Thay vì lặp lại mã bằng tay, ta mô tả quy luật để máy tính thực hiện.':'Bắt đầu bằng cách định nghĩa khái niệm chính, sau đó giải thích bằng một ví dụ gần gũi.'}</p><blockquote>${c.id==='stats'?'Tung một xúc xắc cân đối. Biến cố A = “xuất hiện số chẵn”. Có 3 kết quả thuận lợi trong 6 kết quả đồng khả năng.':c.id==='english'?'“I usually start work at nine. In the morning, I check my emails. Then I meet with my team.”':c.id==='python'?'for item in numbers:\n    print(item * 2)':'Bạn hiểu ý này như thế nào? Hãy tìm một ví dụ cụ thể để kiểm tra cách hiểu.'}</blockquote><h3>${c.id==='stats'?'Điều kiện nào đang được giả định?':'Dừng lại và tự thử'}</h3><p>${c.id==='stats'?'Cách tính bằng số kết quả thuận lợi chia tổng số kết quả cần giả định các kết quả đồng khả năng. Nếu xúc xắc bị lệch, chỉ đếm thôi là chưa đủ.':'Hãy tự thay đổi ví dụ theo tình huống của bạn, rồi nói với gia sư điều bạn chưa chắc. Việc tự thử giúp nhận ra chỗ cần học thêm.'}</p><div class="reading-question">✧ ${c.id==='stats'?'Nếu hai biến cố độc lập, liệu chúng có thể xảy ra cùng lúc không?':'Bạn có thể tìm một ví dụ khác hoặc trường hợp cách này chưa phù hợp không?'}</div><button class="textbutton" data-study-prompt="Giải thích ý này bằng ví dụ khác">Trao đổi đoạn này với gia sư ↗</button></div>`}
function studyView(c){const fs=filesFor(c),f=fs.find(f=>f.id===sourceFocus)||fs[0];sourceFocus=f?.id;return `<div class="study-toolbar"><span>◉ ${esc(c.lesson)}</span><div><button class="secondary" data-action="quiz">✎ Quiz bài này</button><button class="secondary" data-action="exportNotes">↧ Xuất ghi chú</button></div></div><div class="desk"><section class="reader-pane"><div class="pane-heading"><span>▤ Nguồn đang đọc</span><select id="sourceSelect" aria-label="Chọn nguồn đọc">${fs.map(s=>`<option value="${s.id}" ${f?.id===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><div class="reader-scroll">${readerContent(c,f)}</div><div class="reader-bottom">${fs.length} nguồn trong môn này <button class="textbutton" data-tab="sources">Quản lý nguồn ↗</button></div></section><section class="tutor-pane"><div class="desk-tabs"><button data-mode="chat" class="${studyMode==='chat'?'active':''}">✧ Gia sư</button><button data-mode="notes" class="${studyMode==='notes'?'active':''}">▧ Ghi chú của tôi</button></div>${studyMode==='notes'?`<div class="notes-pane"><div class="eyebrow">ĐÚC KẾT BẰNG LỜI CỦA BẠN</div><textarea id="notes" aria-label="Ghi chú môn học" placeholder="Viết điều bạn vừa hiểu, câu hỏi còn bỏ ngỏ…">${esc(c.notes)}</textarea><div class="muted" id="noteStatus">Lưu riêng cho ${esc(c.name)} trên trình duyệt.</div><button class="secondary" data-action="exportNotes">Xuất thành tệp Markdown ↧</button></div>`:`<div class="desk-chat" id="chatmessages"><div class="message"><small>GIA SƯ · HỘI THOẠI MẪU</small>${c.id==='stats'?'Mình đang ở bài Biến cố & xác suất. Bạn có thể tự giải thích sự khác nhau giữa “độc lập” và “xung khắc” không? Cứ nêu cách hiểu, mình cùng kiểm tra.':`Mình đang học ${esc(c.lesson.toLowerCase())}. Bạn muốn bắt đầu bằng ví dụ, hỏi sâu hơn hay thử bài tập?`}<div class="ref">Ngữ cảnh: ${esc(c.name)} · ${fs.length} nguồn được chọn</div></div>${c.messages.map(m=>`<div class="message ${m.role==='user'?'mine':''}"><small>${m.role==='user'?'BẠN':'GIA SƯ · PHẢN HỒI MẪU'}</small>${esc(m.text)}${m.role!=='user'&&f?.sample?`<button class="citation" data-open-source="${f.id}">▤ Xem nguồn minh họa</button>`:''}</div>`).join('')}</div><div class="desk-chat-bottom"><div class="suggestions"><button data-study-prompt="Giải thích bằng ví dụ khác">Ví dụ khác</button><button data-study-prompt="Phản biện cách hiểu của tao">Phản biện cùng tôi</button><button data-study-prompt="So sánh các nguồn đang chọn">So sánh nguồn</button></div><form class="chatform" id="studyform"><input aria-label="Hỏi gia sư" placeholder="Hỏi, phản biện hoặc nói cách bạn hiểu…" required><button class="primary" aria-label="Gửi cho gia sư">↑</button></form><span class="mock-hint">Hội thoại theo kịch bản mẫu · chưa kết nối AI</span></div>`}</section></div>`}
function practiceView(c){return `<div class="section-intro"><div><h2>Kiểm tra để biết mình cần gì.</h2><p class="muted">Mỗi môn giữ kết quả riêng. Quiz mẫu bám theo chủ đề đang học.</p></div>${pill(c.quiz?'Đã hoàn thành quiz mẫu':'Chưa làm quiz')}</div><div class="practice-grid"><div class="panel practice-feature"><div class="icon-large">${ui('pencil')}</div><div class="eyebrow">BÀI ĐANG HỌC</div><h2>${esc(c.lesson)}</h2><p class="muted">Một câu hỏi mẫu, phản hồi ngay và giải thích cách làm.</p><button class="primary" data-action="quiz">${c.quiz?'Làm lại quiz':'Bắt đầu quiz'} →</button></div><div class="panel"><h3>Tự chọn phạm vi kiểm tra</h3><p class="muted">Thử hình dung cách yêu cầu gia sư tạo đề.</p><label class="form-label">Phạm vi<select id="quizScope"><option>Bài đang học</option><option>Tổng hợp các bài đã học</option><option>Từ tất cả tài liệu của môn</option><option>Tập trung vào phần còn yếu</option></select></label><label class="form-label">Số câu<select id="quizCount"><option>5 câu</option><option>10 câu</option><option>15 câu</option></select></label><button class="secondary full" data-action="quizPreview">Xem đề xuất bài kiểm tra</button><p class="mock-hint">Tạo đề tùy chỉnh cần AI thật. Hiện có 1 câu mẫu mỗi môn.</p></div></div>`}
function telehead(){return `<div class="telehead"><div class="telelogo">${ui('send')}</div><div><strong>Nhịp học trên Telegram</strong><div class="live"><i></i> Mô phỏng · chưa nối bot thật</div></div></div>`}
function scheduleView(){return intro('KẾ HOẠCH CHUNG','Đổi lịch, vẫn giữ nhịp.','Cân đối giữa các môn. Nhắn rõ môn, ngày và giờ — lịch sẽ thay đổi trong bản thử.')+`<div class="schedulegrid"><div class="panel"><div class="panelhead"><h3>Các buổi học sắp tới</h3>${pill('Giờ Việt Nam')}</div><p class="muted">Buổi học của tất cả môn nằm trên cùng một lịch.</p>${sorted().map(c=>`<div class="scheduled-session"><div>${icon(c)}</div><div><span class="subject-small ${c.color}">${esc(c.name)}</span><h3>${esc(c.lesson)}</h3><p>${dateName(c.date)} · ${c.time} · ${c.duration} phút</p></div><button class="textbutton" data-edit-schedule="${c.id}">Đổi lịch ↗</button></div>`).join('')}<div class="notice">Nếu giờ mới đè lên buổi học khác, bot sẽ báo xung đột để bạn chọn lại.</div></div><div class="telegram schedule-tele">${telehead()}<div class="telechat" id="telechat"><div class="bubble">Bạn muốn điều chỉnh buổi nào? Chọn môn bên dưới, rồi nhắn “mai học lúc 20h” hoặc “lùi 30 phút” nhé 🌿</div>${state.tele.map(m=>`<div class="bubble ${m.role==='user'?'user':''}">${esc(m.text)}</div>`).join('')}</div><label class="tele-context">Đang trao đổi lịch môn<select id="teleCourse" aria-label="Chọn môn để dời lịch">${state.courses.map(c=>`<option value="${c.id}" ${courseId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><div class="suggestions"><button data-tele="Mai học lúc 21h nhé">Mai, 21:00</button><button data-tele="Lùi 30 phút">Lùi 30 phút</button><button data-tele="Hôm nay chỉ học 15 phút thôi">Học 15 phút</button></div><form class="chatform" id="teleform"><input aria-label="Nhắn bot giả lập" placeholder="Ví dụ: mai học lúc 21h…" required><button class="primary" aria-label="Gửi">➤</button></form><p class="mock-hint">Lịch và tin nhắn chỉ lưu trong bản thử. Chưa có nhắc tự động.</p></div></div>`}
function openModal(html){$('#modal').innerHTML=`<button class="close" data-action="close" aria-label="Đóng">×</button>${html}`;if(!$('#modal').open)$('#modal').showModal();enhanceUI($('#modal'));bindCommon($('#modal'))}
function sourceModal(id){const f=state.files.find(f=>f.id===id);if(!f)return;openModal(`<div class="eyebrow">${f.sample?'NGUỒN MẪU':'TỆP ĐÃ CHỌN'}</div><h2>${esc(f.name)}</h2><p class="muted">${esc(f.author)} · ${esc(f.kind)}</p><div class="notice">${f.sample?'Tài liệu minh họa giao diện, không có toàn văn sách. Chương và nội dung trên bàn học là mẫu biên soạn riêng.':'Bản thử chỉ lưu tên tệp, chưa tải nội dung hoặc phân tích tài liệu.'}</div><h3 style="margin-top:22px">Dùng cho các môn</h3><div class="suggestions">${state.courses.filter(c=>c.sources.includes(id)).map(c=>`<button data-course="${c.id}" data-tab="sources">${esc(c.name)} ↗</button>`).join('')||'<p class="muted">Chưa gắn vào môn nào.</p>'}</div><button class="secondary" style="margin-top:20px" data-assign="${id}">Gắn vào môn khác</button>`)}
function pickSources(){const c=course();openModal(`<div class="eyebrow">THƯ VIỆN → ${esc(c.name)}</div><h2>Chọn các nguồn cùng học.</h2><p class="muted">Một tài liệu có thể thuộc nhiều môn. Chọn nhiều sách để cùng xây lộ trình.</p><div class="picker-list">${state.files.map(f=>`<label class="picker-item"><input type="checkbox" name="source" value="${f.id}" ${c.sources.includes(f.id)?'checked':''}><span><strong>${esc(f.name)}</strong><small>${esc(f.kind)} · ${f.sample?'Nguồn mẫu':'Chưa phân tích'} · ${esc(f.role)}</small></span></label>`).join('')}</div><button class="primary full" data-action="saveSources">Lưu lựa chọn</button>`)}
function buildPlan(){const c=course(),fs=filesFor(c);if(!fs.length){toast('Chọn ít nhất một tài liệu trước khi tạo lộ trình.');return}openModal(`<div class="eyebrow">ĐỀ XUẤT MINH HỌA · CHƯA ÁP DỤNG</div><h2>Ghép ${fs.length} nguồn thành một đường học.</h2><p class="muted">Mục tiêu: ${esc(c.goal)}</p><label class="form-label">Nguồn làm trục chính<select id="mainSource">${fs.map(f=>`<option value="${f.id}" ${c.primarySource===f.id?'selected':''}>${esc(f.name)}</option>`).join('')}</select></label><label class="form-label">Nhịp học<select id="planPace"><option>Nhẹ nhàng · 2 buổi / tuần</option><option selected>Vừa sức · 3 buổi / tuần</option><option>Tập trung · 5 buổi / tuần</option></select></label><div class="proposal"><strong>Giữ mạch từ sách chính</strong><p>Dùng các nguồn còn lại cho ví dụ, đối chiếu và bài tập.</p><strong>6 chặng học có điểm kiểm tra</strong><p>Kiến thức nền → khái niệm → luyện tập → ứng dụng.</p></div><p class="mock-hint">Cấu trúc mẫu theo môn, không phải AI phân tích sách. Áp dụng sẽ cập nhật lộ trình mẫu, chưa đổi lịch học.</p><button class="primary full" data-action="applyPlan">Áp dụng lộ trình mẫu →</button>`)}
function upload(){openModal(`<div class="eyebrow">THÊM VÀO THƯ VIỆN</div><h2>Tài liệu của bạn, hướng học của bạn.</h2><p class="muted">Chọn nhiều tệp cùng lúc, rồi quyết định dùng cho môn nào.</p><label class="upload-zone">↥<strong>Chọn sách, slide hoặc ghi chú</strong><span>PDF, DOCX, PPTX, TXT, MD</span><input type="file" id="fileUpload" multiple accept=".pdf,.docx,.pptx,.txt,.md"></label><div id="chosenFiles" class="muted"></div><label class="form-label">Gắn vào môn<select id="uploadCourse"><option value="none">Chỉ lưu trong thư viện chung</option>${state.courses.map(c=>`<option value="${c.id}" ${page==='course'&&c.id===courseId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><div class="notice">Chỉ lưu tên tệp trên trình duyệt; không tải lên máy chủ hay đọc nội dung.</div><button class="primary full" style="margin-top:18px" data-action="saveUpload">Thêm tài liệu đã chọn</button>`);$('#fileUpload').onchange=e=>$('#chosenFiles').textContent=Array.from(e.target.files).map(f=>f.name).join(' · ')}
function newCourse(){openModal(`<div class="eyebrow">MỘT HÀNH TRÌNH MỚI</div><h2>Bạn muốn học điều gì?</h2><form id="newCourseForm"><label class="form-label">Tên môn<input id="courseName" maxlength="70" required placeholder="Ví dụ: Machine Learning"></label><label class="form-label">Bạn muốn làm được gì?<input id="courseGoal" maxlength="160" required placeholder="Ví dụ: tự làm một dự án dự đoán đơn giản"></label><p class="muted">Tiếp theo: chọn tài liệu từ thư viện, rồi xem đề xuất lộ trình.</p><button class="primary full">Tạo không gian môn học →</button></form>`);$('#newCourseForm').onsubmit=e=>{e.preventDefault();const name=$('#courseName').value.trim(),goal=$('#courseGoal').value.trim();if(!name||!goal)return;const id='course-'+Date.now();state.courses.push({id,name,goal,icon:'✳',color:['sage','clay','blue'][state.courses.length%3],progress:0,lesson:'Làm quen & đặt mục tiêu',time:'19:00',date:'2026-11-15',duration:30,notes:'',messages:[],sources:[],plan:false,quiz:false});save();$('#modal').close();go('course',id,'sources');toast('Đã tạo môn mới. Chọn tài liệu để bắt đầu.')}}
function assign(id){const f=state.files.find(f=>f.id===id);openModal(`<div class="eyebrow">DÙNG LẠI TÀI LIỆU</div><h2>${esc(f.name)}</h2><p class="muted">Chọn những môn sử dụng tài liệu này.</p><div class="picker-list">${state.courses.map(c=>`<label class="picker-item"><input type="checkbox" name="assign" value="${c.id}" ${c.sources.includes(id)?'checked':''}><span><strong>${esc(c.name)}</strong><small>${esc(c.goal)}</small></span></label>`).join('')}</div><button class="primary full" data-save-assign="${id}">Lưu các môn đã chọn</button>`)}
function quiz(){const c=course(),q=c.id==='stats'?{text:'Tung đồng xu cân đối 3 lần độc lập. Xác suất cả 3 lần đều ra mặt ngửa?',answers:['1/2','1/3','1/8','3/8'],right:2,why:'Ba lần độc lập nên nhân xác suất: 1/2 × 1/2 × 1/2 = 1/8.'}:c.id==='english'?{text:'Câu nào đúng để diễn tả thói quen làm việc hằng ngày?',answers:['I usually start work at nine.','I usually starting work at nine.','I usually starts work at nine.','I usually started work tomorrow.'],right:0,why:'Thói quen dùng hiện tại đơn. Chủ ngữ “I” đi với động từ “start”.'}:c.id==='python'?{text:'Đoạn mã “for x in [1, 2, 3]: print(x * 2)” in ra các số nào?',answers:['1, 2, 3','2, 4, 6','1, 4, 9','6'],right:1,why:'Vòng lặp lần lượt lấy 1, 2, 3 và nhân mỗi số với 2.'}:null;if(!q){openModal('<h2>Chưa có quiz mẫu cho môn này.</h2><p class="muted">Khi nối AI thật, câu hỏi sẽ được tạo từ tài liệu và mục tiêu. Các môn mẫu đã có quiz để thử.</p>');return}openModal(`<div class="eyebrow">${esc(c.name)} · QUIZ MẪU 01 / 01</div><h2>Thử xem bạn đã nắm chắc chưa.</h2><p class="quiz-question">${esc(q.text)}</p><div id="answers">${q.answers.map((a,i)=>`<button data-answer="${i}">${esc(a)}</button>`).join('')}</div><div id="feedback" aria-live="polite"></div>`);$$('[data-answer]').forEach(b=>b.onclick=()=>{const right=Number(b.dataset.answer)===q.right;b.classList.add(right?'correct':'wrong');$('#feedback').textContent=right?'Chính xác! '+q.why:'Chưa đúng. '+q.why;if(right){c.quiz=true;save();toast('Đã lưu kết quả riêng cho '+c.name)}})}
function study(text){const c=course(),t=text.trim();if(!t)return;let r;if(/so sánh|nguồn/i.test(t))r=`Môn này có ${c.sources.length} nguồn. Bản thật sẽ so sánh định nghĩa, giả định và ví dụ rồi dẫn đúng đoạn. Bản thử chưa đọc toàn văn nên không thể khẳng định các sách giống hay khác nhau ở đâu. Bạn có thể chọn nguồn khác bên trái.`;else if(c.id==='stats'&&/phản biện|độc lập|xung khắc/i.test(t))r='Thử kiểm tra mệnh đề “độc lập nghĩa là không thể cùng xảy ra”. Tung hai đồng xu: cả hai cùng ngửa vẫn xảy ra được, với xác suất 1/4. Độc lập là không làm thay đổi xác suất của nhau; xung khắc mới là không thể cùng xảy ra. Bạn thử tìm một ví dụ xung khắc nhé?';else if(c.id==='stats')r='Rút một lá từ bộ bài 52 lá tiêu chuẩn. Xác suất rút lá cơ là 13/52 = 1/4 nếu các lá có khả năng được rút như nhau. Nếu cách rút thiên lệch, phép đếm đơn thuần chưa đủ. Bạn thấy giả định quan trọng ở đâu?';else if(c.id==='english')r='Thử nói: “I usually start work at nine, but today I started earlier.” Vế đầu là thói quen; vế sau kể việc đã xảy ra. Bạn thử thay bằng lịch của mình nhé. Mình sẽ hỏi chỗ chưa rõ thay vì viết hộ toàn bộ.';else if(c.id==='python')r='Với [1, 2, 3], lấy mỗi x và in x * 2 thì kết quả là 2, 4, 6. Nếu muốn giữ kết quả để dùng sau thay vì chỉ in, bạn cần thay đổi gì? Hãy tự thử trước nhé.';else r='Bạn thử đưa ví dụ cụ thể và nói giả định đang dùng. Bản thật sẽ đối chiếu với nguồn của môn. Hiện đây là hội thoại mẫu, chưa có AI đọc tài liệu.';c.messages.push({role:'user',text:t},{role:'assistant',text:r});save();studyMode='chat';tab='study';render()}
function parseTime(t){const m=t.match(/(\d{1,2})\s*(?:h|giờ|:)(\d{1,2})?/i);if(!m)return null;return Number(m[1])>23||Number(m[2]||0)>59?-1:Number(m[1])*60+Number(m[2]||0)}
function shiftDate(d,n){const x=new Date(d+'T12:00:00Z');x.setUTCDate(x.getUTCDate()+n);return x.toISOString().slice(0,10)}
function conflict(c,date,time,duration){const start=Number(time.slice(0,2))*60+Number(time.slice(3));return state.courses.find(o=>{if(o.id===c.id||o.date!==date)return false;const os=Number(o.time.slice(0,2))*60+Number(o.time.slice(3));return start<os+o.duration&&os<start+duration})}
function tele(text){const t=text.trim();if(!t)return;const id=$('#teleCourse')?.value||courseId,c=state.courses.find(c=>c.id===id)||course();courseId=c.id;let date=c.date,time=c.time,duration=c.duration,r,changed=false;const mins=parseTime(t),delay=/lùi|nửa tiếng/i.test(t),dm=t.match(/(\d+)\s*phút/i);if(/mai|hôm nay|lùi|nửa tiếng/i.test(t)||mins!==null||dm){if(/mai/i.test(t))date='2026-11-13';if(/hôm nay/i.test(t))date='2026-11-12';if(delay){let total=Number(c.time.slice(0,2))*60+Number(c.time.slice(3))+(dm?Number(dm[1]):30);if(total>=1440){date=shiftDate(date,Math.floor(total/1440));total%=1440}time=String(Math.floor(total/60)).padStart(2,'0')+':'+String(total%60).padStart(2,'0')}else if(mins!==null){if(mins<0)r='Giờ chưa hợp lệ. Thử “mai học lúc 21h” hoặc “20:30” nhé.';else time=String(Math.floor(mins/60)).padStart(2,'0')+':'+String(mins%60).padStart(2,'0')}if(dm&&!delay)duration=Number(dm[1]);if(!r&&(duration<5||duration>180))r='Mỗi buổi cần từ 5 đến 180 phút. Bạn muốn học bao lâu?';const other=!r&&conflict(c,date,time,duration);if(other)r=`Giờ đó trùng môn ${other.name} (${other.time}, ${other.duration} phút). Mình chưa đổi lịch. Bạn chọn giờ khác nhé — ví dụ “mai học lúc 21h”.`;if(!r){Object.assign(c,{date,time,duration});changed=true;r=`Đã cập nhật ${c.name}: ${dateName(date).toLowerCase()} (${date.slice(8)}/${date.slice(5,7)}) lúc ${time}, ${duration} phút. Đây là lịch mẫu, chưa có thông báo thật. 🌿`}}else r=`Bạn muốn dời môn ${c.name} sang ngày nào, lúc mấy giờ? Thử “mai học lúc 21h”, “lùi 30 phút” hoặc “hôm nay học 15 phút”.`;state.tele.push({role:'user',text:`[${c.name}] ${t}`},{role:'assistant',text:r});save();render();if(changed)toast('Đã cập nhật lịch môn '+c.name)}
function editSchedule(id){const c=state.courses.find(c=>c.id===id);openModal(`<div class="eyebrow">ĐIỀU CHỈNH BUỔI HỌC</div><h2>${esc(c.name)}</h2><form id="editScheduleForm"><label class="form-label">Ngày<input type="date" id="editDate" value="${c.date}" required></label><label class="form-label">Giờ<input type="time" id="editTime" value="${c.time}" required></label><label class="form-label">Thời lượng (phút)<input type="number" min="5" max="180" id="editDuration" value="${c.duration}" required></label><div id="scheduleError" class="muted" role="alert"></div><button class="primary full">Lưu lịch mới</button></form>`);$('#editScheduleForm').onsubmit=e=>{e.preventDefault();const date=$('#editDate').value,time=$('#editTime').value,duration=Number($('#editDuration').value),other=conflict(c,date,time,duration);if(other){$('#scheduleError').textContent='Trùng buổi '+other.name+' lúc '+other.time+'. Chọn giờ khác nhé.';return}Object.assign(c,{date,time,duration});save();$('#modal').close();render();toast('Đã cập nhật lịch')}}
const actions={close:()=>$('#modal').close(),newCourse,upload,pickSources,buildPlan,quiz,reset:()=>{if(confirm('Đặt lại toàn bộ dữ liệu bản thử v2?')){localStorage.removeItem('nhiphoc-v2');location.hash='home';location.reload()}},saveSources:()=>{course().sources=$$('input[name="source"]:checked').map(i=>i.value);save();$('#modal').close();render();toast('Đã cập nhật nguồn của môn')},applyPlan:()=>{const c=course();c.primarySource=$('#mainSource').value;c.pace=$('#planPace').value;c.sources=[c.primarySource,...c.sources.filter(id=>id!==c.primarySource)];c.plan=true;save();$('#modal').close();tab='path';render();toast('Đã áp dụng lộ trình mẫu')},saveUpload:()=>{const input=$('#fileUpload');if(!input.files.length){toast('Chọn ít nhất một tệp trước nhé.');return}const target=state.courses.find(c=>c.id===$('#uploadCourse').value);Array.from(input.files).forEach((f,i)=>{const id='file-'+Date.now()+'-'+i;state.files.push({id,name:f.name,kind:f.name.split('.').pop().toUpperCase().slice(0,6),author:'Tệp của bạn',role:'Chưa phân loại',sample:false});if(target)target.sources.push(id)});save();$('#modal').close();render();toast('Đã thêm tên tài liệu vào thư viện')},switchCourse:()=>openModal(`<div class="eyebrow">CHUYỂN KHÔNG GIAN HỌC</div><h2>Bạn muốn học môn nào?</h2><div class="picker-list">${state.courses.map(c=>`<button class="switch-course" data-course="${c.id}">${icon(c)}<span>${esc(c.name)}</span><span>→</span></button>`).join('')}</div>`),exportNotes:()=>{const c=course(),blob=new Blob(['# '+c.name+'\n\n'+c.notes+'\n\n## Nguồn đang chọn\n'+filesFor(c).map(f=>'- '+f.name).join('\n')],{type:'text/markdown;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='ghi-chu-'+c.id+'.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Đã xuất ghi chú của môn')},quizPreview:()=>{const scope=$('#quizScope').value,count=$('#quizCount').value;openModal(`<div class="eyebrow">ĐỀ XUẤT KIỂM TRA · ${esc(course().name)}</div><h2>${esc(count)} · ${esc(scope)}</h2><p class="muted">Gia sư sẽ lấy câu hỏi từ nguồn, chấm và đề xuất ôn lại phần chưa vững.</p><div class="notice">Chưa tạo đề tùy chỉnh. Bạn có thể làm 1 câu mẫu để xem cách phản hồi.</div><button class="primary full" style="margin-top:20px" data-action="quiz">Làm câu hỏi mẫu →</button>`)}};
function bindCommon(root=document){root.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{$('#modal').close();go(b.dataset.page)});root.querySelectorAll('[data-course]').forEach(b=>b.onclick=()=>{$('#modal').close();go('course',b.dataset.course,b.dataset.tab||'overview')});root.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>actions[b.dataset.action]?.());root.querySelectorAll('[data-open-source]').forEach(b=>b.onclick=()=>sourceModal(b.dataset.openSource));root.querySelectorAll('[data-assign]').forEach(b=>b.onclick=()=>assign(b.dataset.assign));root.querySelectorAll('[data-save-assign]').forEach(b=>b.onclick=()=>{const id=b.dataset.saveAssign,selected=$$('input[name="assign"]:checked').map(i=>i.value);state.courses.forEach(c=>{c.sources=c.sources.filter(s=>s!==id);if(selected.includes(c.id))c.sources.push(id)});save();$('#modal').close();render();toast('Đã cập nhật các môn sử dụng tài liệu')})}
function bind(){enhanceUI();bindCommon();$$('.course-tabs [data-tab], #content button[data-tab]:not([data-course])').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});$$('[data-filter]').forEach(b=>b.onclick=()=>{libraryFilter=b.dataset.filter;render()});if($('#search'))$('#search').oninput=e=>{const pos=e.target.selectionStart;search=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)};$$('[data-remove-source]').forEach(b=>b.onclick=()=>{course().sources=course().sources.filter(id=>id!==b.dataset.removeSource);save();render();toast('Đã bỏ khỏi môn, tài liệu vẫn ở thư viện')});if($('#sourceSelect'))$('#sourceSelect').onchange=e=>{sourceFocus=e.target.value;render()};$$('[data-mode]').forEach(b=>b.onclick=()=>{studyMode=b.dataset.mode;render()});if($('#notes'))$('#notes').oninput=e=>{course().notes=e.target.value;save();$('#noteStatus').textContent='✓ Đã lưu riêng cho môn này trên trình duyệt.'};if($('#studyform'))$('#studyform').onsubmit=e=>{e.preventDefault();study(e.target.querySelector('input').value)};$$('[data-study-prompt]').forEach(b=>b.onclick=()=>study(b.dataset.studyPrompt));if($('#chatmessages'))$('#chatmessages').scrollTop=99999;if($('#teleform'))$('#teleform').onsubmit=e=>{e.preventDefault();tele(e.target.querySelector('input').value)};$$('[data-tele]').forEach(b=>b.onclick=()=>tele(b.dataset.tele));$$('[data-edit-schedule]').forEach(b=>b.onclick=()=>editSchedule(b.dataset.editSchedule));if($('#telechat'))$('#telechat').scrollTop=99999;}
function enhanceUI(root=document){root.querySelectorAll('.primary,.secondary').forEach(b=>b.classList.add('btn'));root.querySelectorAll('.primary').forEach(b=>b.classList.add('btn-primary'));root.querySelectorAll('.secondary').forEach(b=>b.classList.add('btn-outline-secondary'));root.querySelectorAll('.label').forEach(b=>b.classList.add('badge'));root.querySelectorAll('.form-label input,.chatform input,.library-toolbar input').forEach(b=>b.classList.add('form-control'));root.querySelectorAll('.form-label select,.tele-context select').forEach(b=>b.classList.add('form-select'));}
function readHash(){const [p,id,t]=location.hash.slice(1).split('/');if(['home','library','schedule'].includes(p))page=p;else if(p==='course'&&state.courses.some(c=>c.id===id)){page=p;courseId=id;tab=['overview','sources','path','study','practice'].includes(t)?t:'overview'}else page='home';render()}
window.addEventListener('hashchange',readHash);readHash();
